/**
 * Race-session model shared by every data provider and every view. A value the source does not supply is `null`, never a guess.
 *
 * Modes (always shown to the user):
 *   LIVE   - genuine live session data from a connected provider (none is configured yet)
 *   REPLAY - playback of an identified, stored historical dataset
 *   DEMO   - generated by the deterministic simulator; nothing in it is a real result
 */
export type RaceMode = "LIVE" | "REPLAY" | "DEMO";

/** Health of the data source, separate from the session's own status. */
export type SourceStatus = "connecting" | "ok" | "error" | "unconfigured";

export type SessionStatus = "not-started" | "running" | "paused" | "finished" | "unknown";

export type PitState = "none" | "in-pit";

export interface SessionInfo {
  id: string;
  /** e.g. "Race". */
  type: string;
  status: SessionStatus;
  circuitSlug: string;
  circuitName: string;
  /** Leader's current lap (1-based) and race length, when known. */
  lap: number | null;
  totalLaps: number | null;
}

export interface DriverState {
  /** Stable key within the session. */
  id: string;
  /** Short identifier for labels: an established abbreviation, or "#<number>" when only the car number is known. */
  code: string;
  name: string | null;
  number: number | null;
  /** Domain team slug, or null when the source does not say. */
  teamSlug: string | null;
  position: number | null;
  /** Current lap, 1-based. */
  lap: number | null;
  /** Fraction of the lap completed, 0 <= p < 1, measured along the circuit's centerline from the start/finish line. */
  progress: number | null;
  lastLapMs: number | null;
  bestLapMs: number | null;
  /** Seconds behind the leader / the car ahead at the same point of the track. */
  gapToLeaderS: number | null;
  gapAheadS: number | null;
  /** Whole laps behind the leader (0 on the lead lap). */
  lapsDown: number | null;
  pit: PitState | null;
  finished: boolean;
  /** Source sample time for this driver (ms, session clock). */
  sampleT: number;
  stale: boolean;
}

export interface RaceSnapshot {
  mode: RaceMode;
  source: { name: string; status: SourceStatus; detail?: string };
  session: SessionInfo;
  /** In race order when the source supplies one; otherwise in a stable fallback order with `ordered: false`. */
  drivers: DriverState[];
  ordered: boolean;
  /** Session clock (ms) this snapshot describes. */
  t: number;
  /** Fraction of the race / recording elapsed, 0..1, for the timeline (null when unknown). */
  elapsed: number | null;
  /** Increments on discontinuities (reset, seek): views must not interpolate across a change of epoch. */
  epoch: number;
}
